// Fails if a pack's script code holds a character other than ASCII and §. Bedrock draws a whole
// line in a smaller fallback font when it contains a character its default font lacks (…, –, ·, •,
// emoji and the like), so chat, menus and command descriptions stay plain ASCII. Comments may use
// anything. One exception: the Minimap's icons are Private Use Area characters (U+E000-U+F8FF) drawn by Side
// HUD's glyph font, and they live only in packs/map_bp/scripts/glyphs.js (generated by tools/gen-glyphs);
// everywhere else such a character, or a \uE000-\uF8FF escape that would make one, fails too.
// It also fails on a form's .header(): Bedrock draws a form header in a huge font that wraps a pack name over
// two lines (the "My preferences" menu, October 2026). Use .label("§l§6Title") for a section title instead.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
/** The one file allowed private-use characters (the minimap's glyphs). */
const GLYPH_FILE = "map_bp/scripts/glyphs.js";
const isPrivate = (/** @type {number} */ c) => c >= 0xe000 && c <= 0xf8ff;
const problems = [];
for (const folder of readdirSync(join(root, "packs")).sort()) {
  const dir = join(root, "packs", folder, "scripts");
  if (!existsSync(dir)) continue;
  const files = readdirSync(dir, { recursive: true }).map(String).filter((f) => f.endsWith(".js")).sort();
  for (const file of files) {
    const glyphs = `${folder}/scripts/${file.split("\\").join("/")}` === GLYPH_FILE;
    const lines = readFileSync(join(dir, file), "utf8").split("\n");
    let inBlock = false;
    lines.forEach((line, i) => {
      let code = line;
      if (inBlock) {
        const end = code.indexOf("*/");
        if (end < 0) return;
        code = code.slice(end + 2);
        inBlock = false;
      }
      code = code.replace(/\/\*.*?\*\//g, "");
      const open = code.indexOf("/*");
      if (open >= 0) {
        code = code.slice(0, open);
        inBlock = true;
      }
      const comment = code.search(/(^|[^:"'`\\])\/\/(?![^"'`]*["'`]\s*[,)\]}])/);
      if (comment >= 0) code = code.slice(0, comment + 1);
      if (!glyphs && /\\u(\{0*)?(e[0-9a-f]|f[0-8])[0-9a-f]{2}/i.test(code)) {
        problems.push(`packs/${folder}/scripts/${file}:${i + 1}: a private-use escape - the minimap's glyphs live only in packs/${GLYPH_FILE}`);
        return;
      }
      if (/\.header\(/.test(code)) {
        problems.push(`packs/${folder}/scripts/${file}:${i + 1}: a form .header() - Bedrock draws it huge; use .label("§l§6Title")`);
        return;
      }
      for (const ch of code) {
        const c = /** @type {number} */ (ch.codePointAt(0));
        if (glyphs && isPrivate(c)) continue;
        if (c > 127 && ch !== "§") {
          problems.push(`packs/${folder}/scripts/${file}:${i + 1}: "${ch}" (U+${ch.codePointAt(0).toString(16).toUpperCase().padStart(4, "0")}) - use ASCII in game text`);
          break;
        }
      }
    });
  }
}
// English language files are game text too (item names, the Building Book's notes): the same rule. Other
// languages keep their own letters. Known lines waiting for a fix: LANG_KNOWN (the count may only go down).
const LANG_KNOWN = { "build_rp/texts/en_US.lang": 31 }; // Effortless Building's port: ❗ – · ⏳ (social-world track)
for (const folder of readdirSync(join(root, "packs")).sort()) {
  const file = join(root, "packs", folder, "texts", "en_US.lang");
  if (!existsSync(file)) continue;
  const key = `${folder}/texts/en_US.lang`;
  const bad = readFileSync(file, "utf8").split("\n").map((l, i) => [l, i + 1]).filter(([l]) => !/^\s*#/.test(String(l)) && [...String(l)].some((ch) => (ch.codePointAt(0) ?? 0) > 127 && ch !== "§"));
  const known = /** @type {Record<string, number>} */ (LANG_KNOWN)[key] ?? 0;
  if (bad.length > known) for (const [l, n] of bad.slice(0, 10)) problems.push(`packs/${key}:${n}: non-ASCII game text (${bad.length} lines, ${known} known): ${String(l).slice(0, 80)}`);
  else if (bad.length < known) console.warn(`warning: packs/${key} has ${bad.length} non-ASCII lines, fewer than the ${known} known: lower LANG_KNOWN in tools/check-ascii.mjs`);
}

if (problems.length) {
  console.error(problems.join("\n"));
  process.exit(1);
}
console.log("Pack scripts and English language files use plain ASCII (and §) outside comments, and no form headers.");
